import { buildWorkshopSubmission } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const valid = {
  organizer: '  Ada  ',
  email: ' ada@example.com ',
  title: ' Type Systems ',
  format: 'onsite' as const,
  venue: ' Hall A ',
  summary: ' Practical workshop ',
  registrationCloses: '2024-02-29'
};
const success = buildWorkshopSubmission(valid, '2024-02-29');
assert(success.ok, 'valid draft should succeed');
if (success.ok) {
  equal(success.value, {
    organizer: 'Ada', email: 'ada@example.com', title: 'Type Systems', format: 'onsite',
    venue: 'Hall A', summary: 'Practical workshop', registrationCloses: '2024-02-29'
  }, 'successful fields should be trimmed');
  assert(success.value !== valid, 'submission must not alias input');
}
equal(valid, {
  organizer: '  Ada  ', email: ' ada@example.com ', title: ' Type Systems ', format: 'onsite',
  venue: ' Hall A ', summary: ' Practical workshop ', registrationCloses: '2024-02-29'
}, 'input must not be mutated');

const online = buildWorkshopSubmission({ ...valid, format: 'online', venue: ' ignored place ' }, '2024-01-01');
assert(online.ok && online.value.venue === 'Remote', 'online venue should normalize to Remote');

function errorsFor(patch: Record<string, unknown>, earliest = '2024-01-01'): readonly string[] {
  const result = buildWorkshopSubmission({ ...valid, ...patch } as typeof valid, earliest);
  assert(!result.ok, 'case should fail validation');
  return result.ok ? [] : result.errors;
}
const organizerError = errorsFor({ organizer: '   ' });
const emailError = errorsFor({ email: 'a@@b' });
const titleError = errorsFor({ title: '' });
const formatError = errorsFor({ format: 'hybrid' });
const venueError = errorsFor({ venue: ' ' });
const summaryError = errorsFor({ summary: ' ' });
const closesError = errorsFor({ registrationCloses: '2023-12-31' });
const earliestResult = buildWorkshopSubmission(valid, '2023-02-29');
assert(!earliestResult.ok, 'invalid earliest date should be reported');
const earliestError = earliestResult.ok ? [] : earliestResult.errors;
for (const errors of [organizerError, emailError, titleError, formatError, venueError, summaryError, closesError, earliestError]) {
  assert(errors.length === 1, 'one invalid field should yield one error');
}
const allInvalid = buildWorkshopSubmission({
  organizer: ' ', email: 'bad', title: ' ', format: 'hybrid' as never,
  venue: ' ', summary: ' ', registrationCloses: '2023-02-29'
}, '2023-02-29');
assert(!allInvalid.ok, 'fully invalid draft should fail');
if (!allInvalid.ok) {
  const expected = [organizerError[0], emailError[0], titleError[0], formatError[0], venueError[0], summaryError[0], closesError[0], earliestError[0]];
  equal(allInvalid.errors, expected, 'errors should be unique and follow validation order');
  assert(new Set(allInvalid.errors).size === allInvalid.errors.length, 'errors must be unique');
}

assert(errorsFor({ email: '@example.com' }).length === 1, 'email needs text before @');
assert(errorsFor({ email: 'a@' }).length === 1, 'email needs text after @');
assert(errorsFor({ registrationCloses: '2024-2-01' }).length === 1, 'date format must be exact');
assert(errorsFor({ registrationCloses: '2024-04-31' }).length === 1, 'date must be Gregorian');
assert(errorsFor({ organizer: 4 }).length === 1, 'non-string fields must be rejected');

